+/// Tells all workers to quit when dropped while panicking.
+///
+/// Workers rely on each other to figure out when all of the work is done, so
+/// a worker that dies without telling anyone would otherwise leave the others
+/// waiting for it forever.
+struct QuitOnPanic(Arc<AtomicBool>);
+
+impl Drop for QuitOnPanic {
+    fn drop(&mut self) {
+        if std::thread::panicking() {
+            self.0.store(true, AtomicOrdering::SeqCst);
+        }
+    }
+}
